import {courseLesson,edit} from './utility-authoring.js';
const L=(...args)=>courseLesson("object",...args);
export const objectUtilsLessons=[
L("property","Distinguish inherited, defined and readable properties",[0, 19, 21, 20],"<p>A property can exist on a child because its parent defines it. Definition and readability are separate questions. Builtin properties such as <code>name</code> have special rules. The example creates and recycles two private objects.</p>","root = create(#-1);\nchild = create(root);\nadd_property(root, \"sample\", 7, {player, \"rc\"});\nplayer:tell(\"HAS inherited: \", toliteral($object_utils:has_property(child, \"sample\")));\nplayer:tell(\"DEFINES on child: \", toliteral($object_utils:defines_property(child, \"sample\")));\nplayer:tell(\"READABLE: \", toliteral($object_utils:has_readable_property(child, \"sample\")));\nplayer:tell(\"ANY own properties: \", toliteral($object_utils:has_any_property(child)));\nrecycle(child);\nrecycle(root);",edit("\"sample\", 7","\"sample\", 9","Change the property value to nine. Existence, definition and permission results stay unchanged.")),
L("definition","Find where a verb is defined and callable",[2, 3, 4, 18],"<p><code>has_verb()</code> reports a defining object in a list; <code>defines_verb()</code> answers whether it is directly defined. <code>has_callable_verb()</code> checks the execute permission. <code>match_verb()</code> also returns a usable name. Print the target definition rather than confusing it with the receiver.</p>","target = $list_utils;\nname = \"range\";\nplayer:tell(\"HAS VERB: \", toliteral($object_utils:has_verb(target, name)));\nplayer:tell(\"CALLABLE: \", toliteral($object_utils:has_callable_verb(target, name)));\nplayer:tell(\"MATCH VERB: \", toliteral($object_utils:match_verb(target, name)));\nplayer:tell(\"DEFINES VERB: \", toliteral($object_utils:defines_verb(target, name)));",edit("name = \"range\";","name = \"make\";","Inspect make instead of range. The defining object stays List Utils and the resolved name changes.")),
L("inheritance","Follow an inheritance tree",[5, 6, 7, 17, 22],"<p>Inheritance describes type relationships, not physical containment. <code>ancestors()</code> excludes the object itself. <code>ordered_descendants()</code> includes its root; <code>descendants()</code> excludes it. <code>isoneof()</code> walks the parent chain looking for any supplied ancestor.</p>","root = create(#-1);\nchild = create(root);\nadd_property(root, \"sample\", 7, {player, \"rc\"});\nplayer:tell(\"ISA child root: \", toliteral($object_utils:isa(child, root)));\nplayer:tell(\"ANCESTOR count: \", toliteral(length($object_utils:ancestors(child))));\nplayer:tell(\"DESCENDANT count: \", toliteral(length($object_utils:descendants(root))));\nplayer:tell(\"ORDERED including root: \", toliteral(length($object_utils:ordered_descendants(root))));\nplayer:tell(\"ISONEOF: \", toliteral($object_utils:isoneof(child, {root})));\nrecycle(child);\nrecycle(root);",edit("isa(child, root)","isa(root, child)","Reverse the inheritance question. A parent is not a descendant of its child.")),
L("tree-ends","Identify leaves and branches",[23, 24, 25, 26, 27],"<p>Leaves have no children; branches have children. These implementations can include the root when it qualifies. Suspended variants add scheduler checkpoints but should return the same structural result for this small tree.</p>","root = create(#-1);\nchild = create(root);\nadd_property(root, \"sample\", 7, {player, \"rc\"});\nplayer:tell(\"LEAVES count: \", toliteral(length($object_utils:leaves(root))));\nplayer:tell(\"BRANCHES count: \", toliteral(length($object_utils:branches(root))));\nplayer:tell(\"DESCENDANTS suspended: \", toliteral(length($object_utils:descendants_suspended(root))));\nplayer:tell(\"LEAVES suspended: \", toliteral(length($object_utils:leaves_suspended(root))));\nplayer:tell(\"BRANCHES suspended: \", toliteral(length($object_utils:branches_suspended(root))));\nrecycle(child);\nrecycle(root);",edit("leaves(root)","leaves(child)","Ask for leaves starting at the child. The leaf count remains one because the child itself qualifies.")),
L("containment","Separate containment from inheritance",[8, 9, 14],"<p>Containment follows <code>location</code> and <code>contents</code>. An object may inherit from one object while being physically inside another. This empty private object is not moved, so it has neither contents nor a containing location.</p>","box = create(#-1);\nplayer:tell(\"CONTAINS itself: \", toliteral($object_utils:contains(box, box)));\nplayer:tell(\"ALL CONTENTS: \", toliteral($object_utils:all_contents(box)));\nplayer:tell(\"LOCATIONS: \", toliteral($object_utils:locations(box)));\nrecycle(box);",edit("contains(box, box)","contains(box, player)","Ask whether the empty box contains the player. It remains false; ownership does not imply containment.")),
L("enumeration","List inherited and accessible members",[1, 10, 11, 15, 29, 30],"<p>All-members helpers include ancestors. Findable properties depend on object readability; owned properties depend on property ownership. Accessible helpers inspect individual member permissions. These lists can differ without any member disappearing.</p>","root = create(#-1);\nchild = create(root);\nadd_property(root, \"sample\", 7, {player, \"rc\"});\nplayer:tell(\"ALL properties: \", toliteral($object_utils:all_properties(child)));\nplayer:tell(\"ALL properties suspended: \", toliteral($object_utils:all_properties_suspended(child)));\nplayer:tell(\"ALL verbs: \", toliteral($object_utils:all_verbs(child)));\nplayer:tell(\"ALL verbs suspended: \", toliteral($object_utils:all_verbs_suspended(child)));\nplayer:tell(\"FINDABLE: \", toliteral($object_utils:findable_properties(child)));\nplayer:tell(\"OWNED: \", toliteral($object_utils:owned_properties(child)));\nplayer:tell(\"ACCESSIBLE properties: \", toliteral($object_utils:accessible_properties(root)));\nplayer:tell(\"ACCESSIBLE verbs: \", toliteral($object_utils:accessible_verbs(root)));\nrecycle(child);\nrecycle(root);",edit("\"sample\", 7","\"quantity\", 7","Rename the property to quantity. Every property listing that included sample now includes quantity.")),
L("reparenting","Check conflicts before changing inheritance",[12, 13],"<p>Changing a parent can conflict with a property defined below the object. <code>property_conflicts()</code> reports those names and defining objects. <code>descendants_with_property_suspended()</code> stops at the first definition along each branch. This example checks only; it does not change parents.</p>","root = create(#-1);\nchild = create(root);\nadd_property(root, \"sample\", 7, {player, \"rc\"});\nother = create(#-1);\nadd_property(other, \"sample\", 2, {player, \"rc\"});\nplayer:tell(\"CONFLICT count: \", toliteral(length($object_utils:property_conflicts(root, other))));\nplayer:tell(\"DEFINITION locations count: \", toliteral(length($object_utils:descendants_with_property_suspended(root, \"sample\"))));\nrecycle(other);\nrecycle(child);\nrecycle(root);",edit("\"sample\", 2","\"other_value\", 2","Give the proposed parent a different property name. The conflict count becomes zero.")),
L("connections","Check connection state without assuming presence",[16],"<p><code>connected()</code> tests for a live player connection. An object existing in the world does not imply a connection. The browser learner has no real network connection; a live server\u2019s result depends on who is logged in.</p>","player:tell(\"UTILITY connected: \", toliteral($object_utils:connected($list_utils)));\nplayer:tell(\"ROOM connected: \", toliteral($object_utils:connected(this)));",edit("connected($list_utils)","connected($string_utils)","Check String Utils instead. Utility objects are not connected players.")),
L("disinherit","Understand an owner\u2019s disinheritance boundary",[28],"<p><code>disown()</code>, also named <code>disinherit()</code>, lets an owner remove someone else\u2019s child from their parent object, moving it to the grandparent. It rejects objects you control: use the normal parent-changing tools for those. The example deliberately exercises that guard on a temporary object.</p>","temporary = create(#-1);\nplayer:tell(\"DISOWN owned object guard: \", toliteral(`$object_utils:disown(temporary) ! ANY'));\nrecycle(temporary);",edit("disown(temporary)","disinherit(temporary)","Call the alias. It follows the same ownership guard and returns the same caught error.")),
L("inspection-report","Assemble an object inspection report",[],"<p>Report identity separately from inheritance and member availability. Use the execution target as data; this report does not change which object runs your Code tab.</p>","target = $list_utils;\nplayer:tell(\"OBJECT name: \", toliteral(target.name));\nplayer:tell(\"ANCESTOR count: \", toliteral(length($object_utils:ancestors(target))));\nplayer:tell(\"RANGE callable: \", toliteral($object_utils:has_callable_verb(target, \"range\")));",edit("target = $list_utils;","target = $set_utils;","Inspect Set Utils instead. Its name changes and range is no longer a callable member.")),
];
export const objectExclusions={};
